function lightestHeaviestPair(weights: number[]): number {
  const go = (rest: number[]): number => {
    if (rest.length === 0) return 0;
    let best = Infinity;
    for (let j = 1; j < rest.length; j++) {
      const others = rest.filter((_, i) => i !== 0 && i !== j);
      best = Math.min(best, Math.max(rest[0] + rest[j], go(others)));
    }
    return best;
  };
  return go(weights);
}

