function lightestHeaviestPair(weights: number[]): number {
  const w = [...weights].sort((a, b) => a - b);
  let best = 0;
  for (let lo = 0, hi = w.length - 1; lo < hi; lo++, hi--) {
    best = Math.max(best, w[lo] + w[hi]);
  }
  return best;
}

